import { writeFile } from 'node:fs/promises';

// Never copy arbitrary environment values or secrets into an artifact. Non-staging,
// missing and malformed build identities always replace any previous staging grant.
export async function writeV2BuildIdentity() {
  const allowed = process.env.CONTEXT === 'branch-deploy' && process.env.BRANCH === 'staging';
  const identity = allowed ? { version: 1, context: 'branch-deploy', branch: 'staging' } : null;
  await writeFile(new URL('../netlify/functions/lib/v2/deployment-identity.mjs', import.meta.url),
    '// Generated by the trusted build; server-only, not runtime environment configuration.\n' +
    'export default Object.freeze(' + JSON.stringify(identity) + ');\n');
}
